import json,math,pathlib
R=json.load(open('final_results.json'))
OUT=pathlib.Path('models');OUT.mkdir(exist_ok=True)

def row(name,value,unit,description,typ='fitted',equation=None):
 d={'name':name,'value':float(value),'unit':unit,'type':typ,'description':description}
 if equation is not None:d['equation']=equation
 return d

def shared(t):
 return [row('a',t[0],'bar/(s*(l/min))','Positive inlet conversion gain `a`: estimated jointly with all other fitted parameters in the pressure-simulation fit; represents gas storage and standard-volume conversion together, not independently measured tank volume.'),row('patm',t[2],'bar','Effective atmospheric equilibrium `patm`, estimated jointly in the pressure-simulation fit with bounds `0.985 <= patm <= 1.01` bar. These bounds admit a small pressure-calibration/ambient offset around the task\'s approximate atmospheric level while excluding the markedly lower equilibrium demanded by the rejected linear-outflow fit. This is not a barometer measurement.')]

def logistic(t,cunit):
 p=[row('c',t[1],cunit,'Outlet coefficient `c` at the reference closure `vref`, estimated jointly; the interpretation of its units follows the candidate pressure-drive law.'),row('vmid',t[5],'%','Sigmoid location `vmid`, estimated jointly; controls where valve conductance changes most rapidly, without asserting an actual geometric port location.'),row('vwidth',t[6],'%','Positive sigmoid width `vwidth`, estimated jointly; controls the smoothness of the calibrated conductance decrease.'),row('vmax',100.,'%','Full-closure endpoint `vmax = 100` % from the task definition; fixed to enforce a sealed outlet at that endpoint.','fixed'),row('vref',70.,'%','Reference closure `vref = 70` % chosen before fitting to lie in the dense training-input region and to normalize `c`; no physical threshold is asserted.','fixed')]
 sc=1/(1+math.exp((100-t[5])/t[6]));sr=1/(1+math.exp((70-t[5])/t[6]))
 p += [row('sclosed',sc,'-','Endpoint sigmoid ordinate `sclosed`, tied rather than separately fitted, so full closure has exactly zero nonnegative conductance.','tied','1/(1+exp((vmax-vmid)/vwidth))'),row('sref',sr,'-','Reference sigmoid ordinate `sref`, tied to the fitted valve curve so `c` is its reference coefficient.','tied','1/(1+exp((vref-vmid)/vwidth))')]
 C='c*Max(0,1/(1+exp((Min(Max(valve,0),vmax)-vmid)/vwidth))-sclosed)/(sref-sclosed)'
 return p,C

def physical(extra=''):
 return ' Physical requirements: R1 holds because the derivative with respect to inlet `flow` is the fitted positive `a`. R2 holds for `p >= patm`: conductance is nonnegative and nonincreasing in `valve`, and the outlet pressure drive is nonnegative. All supplied pressure observations exceed the final fitted `patm`. A passive bidirectional outlet necessarily reverses the R2 sign below `patm`, because closing it also suppresses atmospheric air admission; therefore literal R2 is not claimed in that unobserved sub-atmospheric regime. R3 holds exactly at `p = patm` with `flow = 0`, for every valve opening, and `patm` is approximately the task\'s `1` bar. R4 holds in continuous time on either side of `patm`, because the outlet term has the sign of `p-patm` and opposes it whenever the outlet is open. R5 holds exactly at `valve = vmax` or the full-closure endpoint: outlet conductance is zero and `dp = a*flow >= 0` for `flow >= 0`. No measured inlet-flow sample was exactly zero and neither experiment reached full closure, so those endpoints are assumptions rather than empirical verifications.'+extra

NASA='The ideal-gas storage basis is the NASA Glenn Beginner\'s Guide to Aeronautics, "Equation of State" (page last updated May 13, 2021), read during this round. The isentropic/choked-flow reference is the same guide\'s "Mass Flow Choking" (page last updated May 13, 2021), also read during this round. Neither source determines the rig\'s fitted valve characteristic or the empirical smoothing.'

def est(label,method,startnames,units,bounds,extra=''):
 z=R[label];tr=z['train_only'];tstart=tr.get('initial',None)
 def fmt(values):return ', '.join('`'+n+' = '+format(float(v),'.12g')+'`'+(' '+u if u else '') for n,v,u in zip(startnames,values,units))
 if label=='MixedOutlet':
  first=tr['starting_values'];second=z['starting_values']
 else:
  idx=z['active'];first=[tr['initial'][i] for i in idx];second=[z['initial'][i] for i in idx]
 pooled=math.sqrt((1451*z['rmse']['train']**2+1453*z['rmse']['val']**2)/2904)
 return {'criterion':'Unweighted sum of squared free-running pressure errors, in bar squared, over every sample after the initial one. Each trajectory is initialized only at its first logged `p`; current-row `valve` and `flow` are held constant during a classical RK4 step of `5` s. The final fit has `2904` pressure residuals, with `1451` from training and `1453` from validation. This directly matches the intended long-horizon simulation criterion instead of fitting the filtered `dp` column. Final training RMSE is '+format(z['rmse']['train'],'.9g')+' bar and final validation-data RMSE is '+format(z['rmse']['val'],'.9g')+' bar; the pooled supplied-data RMSE is '+format(pooled,'.9g')+' bar. Validation data are part of this final estimation objective, not an independent performance test.',
 'data':'All rows of `data/train.csv` (one trajectory, `1452` samples) and `data/val.csv` (one separate trajectory, `1454` samples). The initial samples are used to initialize simulations but not to score residuals. A training-only preliminary fit used only `data/train.csv`; its validation RMSE was '+format(tr['rmse']['val'],'.9g')+' bar. Validation was first used for structural comparison and residual inspection, then included in the final joint fit to improve input/pressure coverage. The experiments are never concatenated into one state trajectory; no rows are excluded and no future inputs are used.',
 'method':'Bound-constrained nonlinear least squares with the Trust Region Reflective algorithm, `scipy.optimize.least_squares`, using two-point finite-difference Jacobians and `x_scale = \'jac\'`. This is used because the closed-form model is nonlinear in the coefficients and the criterion includes recursive state integration; ordinary linear least squares cannot minimize this objective. Numba compiles only the model and RK4 loops; it does not change the integration rule. First all fitted coefficients were estimated together against training-trajectory simulation; all were then re-estimated together against the two independently initialized trajectories in one combined objective. Training-fit starting values: '+fmt(first)+'. These scales were chosen to represent an approximately nominal gas-storage gain, an outlet coefficient of comparable magnitude, an equilibrium close to atmosphere, and moderate valve/pressure nonlinearities rather than an extreme initial stiffness. Joint-fit starting values: '+fmt(second)+'. They are the converged training values'+(' except that `kappa` is reset to `0.48` 1/s to start strictly inside its numerical-stability bound.' if label=='MixedOutlet' else ', to retain a physically plausible training optimum as the initial point.')+' '+method+' Bounds: '+bounds+'. Maximum function evaluations per stage: `350`'+('' if label in ['MixedOutlet','SeriesPipe','Compressible'] else ' for resistance models, but this candidate uses `300`')+'. For this candidate the actual maximum is `'+str(300 if label=='ValvePower' else 350)+'`. Stopping tolerances `ftol = 1e-10`, `xtol = 1e-10`, and `gtol = 1e-10` are the dimensionless solver settings, not data-derived noise levels. No random numbers or stochastic search were used; no seed applies. '+extra,
 'script':'fit_candidates.py'}

# mixed linear-quadratic pressure resistance with sigmoid conductance and constrained fastest rate
label='MixedOutlet';z=R[label];t=z['params'];p=shared(t);lp,C=logistic(t,'bar**0.5/s');p+=lp
copen=t[1]*(1/(1+math.exp(-t[5]/t[6]))-p[-2]['value'])/(p[-1]['value']-p[-2]['value'])
k=z['fit_values'][5]
p += [row('kappa',k,'1/s','Maximum atmospheric pressure-relaxation rate `kappa` at the fully open valve, estimated jointly with the other fitted coefficients subject to `0.01 <= kappa <= 0.5` 1/s. The upper bound is chosen for numerical stability, not inferred as a fundamental property.'),row('copen',copen,'bar**0.5/s','Fully open outlet coefficient `copen`, computed from the fitted sigmoid and reference coefficient, not independently estimated.','tied','c*(1/(1+exp((0-vmid)/vwidth))-sclosed)/(sref-sclosed)'),row('delta',(copen/k)**2,'bar','Viscous-to-inertial crossover pressure `delta`, tied to `copen` and the estimated fastest rate `kappa`; this reparameterization enforces a stable atmospheric relaxation rate.','tied','(copen/kappa)**2')]
expr='a*flow - ('+C+')*2*(p-patm)/(sqrt(delta)+sqrt(delta+4*Abs(p-patm)))'
model={'expressions':{'dp':expr},'parameters':p,'estimation':est(label,'The fitted `kappa` replaces direct estimation of `delta`, with the tie `delta = (copen/kappa)**2`; the fixed upper rate `0.5` 1/s makes the worst-case RK4 relaxation product at the task\'s `5` s step equal to `2.5`, below the classical negative-real-axis stability limit of approximately `2.785`. The optimum reaches that rate bound and the lower atmospheric bound.', ['a','c','patm','vmid','vwidth','kappa'],['bar/(s*(l/min))','bar**0.5/s','bar','%','%','1/s'],'`0.0001 <= a <= 0.004` bar/(s*(l/min)), `0.0001 <= c <= 0.3` bar**0.5/s, `0.985 <= patm <= 1.01` bar, `0 <= vmid <= 98` %, `2 <= vwidth <= 70` %, and `0.01 <= kappa <= 0.5` 1/s'),
'discussion':{'family':'Nonlinear ideal-gas storage balance with mixed linear-quadratic outlet resistance (a Darcy-Forchheimer-type constitutive law) and monotone sigmoid valve calibration. Its signed outlet law is obtained by solving a positive linear-plus-quadratic pressure-drop relation for flow; that algebraic derivation, rather than a porous-media assumption, is used here. '+NASA,
'interpretation':'The term `a*flow` is inlet mass accumulation converted to pressure rate. Let `C = '+C+'` denote the outlet coefficient, solely as notation in this discussion; no extra state is simulated. The signed discharge `C*2*(p-patm)/(sqrt(delta)+sqrt(delta+4*Abs(p-patm)))` has a linear low-drop limit and an inertial square-root high-drop limit. The logistic curve calibrates positive decreasing conductance, while its endpoint subtraction gives an exactly sealed full-closure outlet. `vmid` and `vwidth` describe that calibration, not measured valve geometry. `patm` is an effective sensor-level atmospheric equilibrium. `kappa` and its tie define the fastest zero-flow relaxation, making numerical stability explicit.',
'origin':'Mass conservation supplied `a*flow` minus an outlet term; atmospheric relaxation supplied the signed pressure excess. Early linear-pressure drives gave supplied-trajectory RMSE of approximately `0.06` bar and were rejected. Regularized square-root and generalized-power drives improved simulation. Residual pressure-bin biases near atmospheric pressure suggested a finite low-drop conductance, so this mixed viscous/inertial law was tried as a physically defensible interpolation rather than an unconstrained polynomial. The sigmoid conductance was chosen after simple open-fraction power and exponential curves; its saturating open-end calibration marginally improved training-only validation accuracy. The unconstrained mixed fit had a fully-open atmospheric relaxation rate above the stable RK4 range; the `kappa` reparameterization was added after checking this, at a small fit cost. No symbolic-regression-generated terms are used.',
'limitations':'Ambient pressure, pressure-sensor offset, temperature, exact effective gas volume, and standard-flow calibration are not separately identified. The final `patm = '+format(t[2],'.9g')+'` bar is at its assumed lower bound and `kappa = '+format(k,'.9g')+'` 1/s is at its stability bound, so neither should be interpreted as an independently measured physical constant. The fit absorbs some unmodelled dynamics and the apparent one-sample flow logging mismatch. The training-only validation RMSE is reported separately from final in-sample validation-data RMSE. The model cannot represent temperature dynamics, delays, bubble inventory, leaks or valve hysteresis. Clipping outside `0 <= valve <= 100` % is a numerical extension, not a calibrated extrapolation.'+physical()}}
json.dump(model,open(OUT/(label+'.json'),'w'),indent=2)

# series fixed line resistance + valve inertial resistance
label='SeriesPipe';z=R[label];t=z['params'];p=shared(t)
p += [row('c',t[1],'bar**0.5/s','Reference inertial outlet coefficient `c`, jointly estimated.'),row('beta',t[4],'-','Positive open-fraction power `beta`, jointly estimated; determines how inertial conductance closes with the valve.'),row('ell',t[17],'s','Positive linear pressure-drop coefficient `ell`, jointly estimated. In pressure-rate units it is the fixed-line viscous resistance; its reciprocal bounds the small-drop relaxation rate.'),row('vmax',100.,'%','Full-closure endpoint `vmax = 100` % from the task definition; not fitted.','fixed'),row('vscale',30.,'%','Open-fraction scale `vscale = 30` % chosen to normalize inertial conductance at `valve = 70` %, within dense training coverage.','fixed'),row('epsdrop',1e-8,'bar','Fixed squared-denominator regularization `epsdrop = 1e-8` bar prevents the removable zero divided by zero at full closure and atmospheric pressure. It was chosen as a tiny positive scale compared with measured pressure excesses, not estimated; its effect is negligible except at that singular endpoint.','fixed')]
C='c*(Min(Max(vmax-valve,0),vmax)/vscale)**beta'
expr='a*flow - 2*('+C+')*(p-patm)/(ell*('+C+')+sqrt((ell*('+C+'))**2+4*Abs(p-patm)+epsdrop))'
model={'expressions':{'dp':expr},'parameters':p,'estimation':est(label,'Only `a`, `patm`, `ell`, `c`, and `beta` are fitted. A separate exponent for the linear resistance was initially tried, but its incremental accuracy was too small to justify another uncertain parameter; this candidate fixes the line resistance independent of `valve`. No derivative prefit determines its coefficients.', ['a','patm','ell','c','beta'],['bar/(s*(l/min))','bar','s','bar**0.5/s',''],'`0.0001 <= a <= 0.004` bar/(s*(l/min)), `0.985 <= patm <= 1.01` bar, `0.01 <= ell <= 30` s, `0.0001 <= c <= 0.3` bar**0.5/s, `0.1 <= beta <= 8`'),
'discussion':{'family':'Lumped gas-storage model with a series combination of fixed viscous line resistance and valve-dependent inertial resistance. This is a mixed linear-quadratic pressure-drop model, solved explicitly for the signed outlet flow. '+NASA,
'interpretation':'The inlet term is `a*flow`. Write `C = '+C+'` for the reference-normalized inertial coefficient. Neglecting only the tiny endpoint regularization, the outlet pressure-rate quantity `qout` solves `p-patm = ell*qout + qout*Abs(qout)/C**2`. This equation is dimensional in bar because `ell` has units s and `C` has units bar**0.5/s. The delivered radical is the explicit solution; it combines the fixed line resistance and closing-valve inertial resistance in series rather than multiplying one universal pressure curve by a valve coefficient. `beta` gives a monotone valve calibration and the exact zero coefficient at full closure. The two terms represent distinct pressure-drop mechanisms; their coefficients cannot be converted to actual pipe dimensions without independent gas-storage and temperature calibration.',
'origin':'Starting from the same conservation law, pressure residuals of separable square-root models motivated a pressure crossover that varies with valve opening. A fixed linear line loss together with a closing-valve quadratic loss supplies this dependence automatically. It was proposed and fitted after the separable drive screen; a version allowing a valve-dependent linear-resistance exponent and pressure-squared compressible variants were also tried. The extra linear exponent gave a negligible validation advantage, so this more parsimonious five-coefficient series model was retained. The open-fraction power curve was chosen because it is monotone, low-dimensional, positive and exactly sealed at full closure.',
'limitations':'`ell` is an effective resistance in pressure-rate units, not a measured pipe friction coefficient; gas storage, temperature and geometry are confounded. The model uses low-Mach mixed resistance rather than a full choked nozzle law, so high-pressure extrapolation beyond the supplied approximately `2.19` bar maximum is uncertain. Its largest zero-flow local relaxation rate is bounded by `1/ell = '+format(1/t[17],'.9g')+'` 1/s, which is below the RK4 rate limit for a `5` s step. The tiny `epsdrop` regularization is numerical rather than an independently supported microscopic flow law. Input logging mismatch and additional unmodelled states still leave correlated residuals.'+physical()}}
json.dump(model,open(OUT/(label+'.json'),'w'),indent=2)

# calibrated generalized pressure power with monotone piecewise linear valve characteristic
label='ValvePower';z=R[label];t=z['params'];p=shared(t)
p += [row('delta',t[3],'bar','Positive pressure-drive smoothing scale `delta`, jointly estimated; ensures finite atmospheric relaxation rather than a singular square-root derivative.'),row('n',t[7],'-','Positive generalized pressure-drop exponent `n`, jointly estimated; it interpolates between linear and square-root-like discharge but is not asserted to be a literal Reynolds-number exponent.'),row('pscale',1.,'bar','Canonical pressure scale `pscale = 1` bar, fixed solely to make the generalized power dimensionally meaningful; it changes no numerical prediction in the task\'s bar convention.','fixed')]
knots=[0.,30.,50.,65.,75.,85.,95.,100.]
for j,val in enumerate(knots):p.append(row('k'+str(j+1),val,'%','Fixed valve-knot `k'+str(j+1)+' = '+str(val)+'` %; endpoints follow the task definition, and interior knots were chosen before this fit to cover the broad-open region coarsely and the densely sampled closing region more finely. This is a constitutive calibration grid, not an estimated threshold.','fixed'))
for j,val in enumerate(t[10:17]):p.append(row('s'+str(j+1),val,'1/(s*%)','Nonnegative conductance slope magnitude `s'+str(j+1)+'` on interval `k'+str(j+1)+' <= valve <= k'+str(j+2)+'`, jointly estimated in the simulation fit; each slope contributes only a monotone calibration increment.'))
C=' + '.join('s'+str(j+1)+'*Min(Max(k'+str(j+2)+'-valve,0),k'+str(j+2)+'-k'+str(j+1)+')' for j in range(7))
H='pscale*((p-patm)/pscale)*(((p-patm)/pscale)**2+(delta/pscale)**2)**((n-1)/2)'
expr='a*flow - ('+C+')*('+H+')'
model={'expressions':{'dp':expr},'parameters':p,'estimation':est(label,'The seven nonnegative valve slopes and `a`, `patm`, `delta`, and `n` are fitted simultaneously. Nonnegative slopes guarantee a decreasing calibrated outlet coefficient without relying on sparse-polynomial cancellations. The reference `c` and unused exploratory valve parameters are not part of this delivered model.', ['a','patm']+['s'+str(j+1) for j in range(7)]+['delta','n'],['bar/(s*(l/min))','bar']+['1/(s*%)']*7+['bar',''],'`0.0001 <= a <= 0.004` bar/(s*(l/min)), `0.985 <= patm <= 1.01` bar, `0 <= s1,s2,s3,s4,s5,s6,s7 <= 0.006` 1/(s*%), `0.003 <= delta <= 2` bar, and `0.25 <= n <= 1.2`'),
'discussion':{'family':'Shape-constrained nonlinear grey-box state-space model: ideal-gas storage, regularized signed generalized-power discharge, and a monotone piecewise-linear valve-conductance calibration. The constitutive calibration is a constrained regression, not a discovered exact valve equation. '+NASA,
'interpretation':'The inlet term `a*flow` is pressure accumulation. The outlet drive `'+H+'` has the sign of excess pressure, finite positive slope at atmospheric pressure, and an approximately `Abs(p-patm)**n` magnitude at high drop. The fitted `n` controls curvature; its mathematical effect is asserted, not a unique physical flow regime. The coefficient `'+C+'` integrates nonnegative interval slope magnitudes from the full-closure endpoint, so conductance is zero there and never increases with closure. `k1` through `k8` are closure knots; `s1` through `s7` are local calibration slopes, not seven different flow paths.',
'origin':'This model retains the physical inlet-minus-outlet balance but replaces guessed sigmoid or power valve geometry with a monotone calibration. It was tried after pressure/input-bin residual inspection of the lower-dimensional outlet models. The generalized pressure exponent was part of the initial physical-family screen; the finite smoothing was retained because a literal square-root drive can become numerically stiff at atmosphere with the required large sample step. Nonnegative hinge increments were selected instead of high-order unconstrained polynomials so valve monotonicity and the sealed endpoint remain explicit. A nonlinear flow-power inlet and compressibility-dependent storage variants were also tested, but were not needed in this retained linear-inlet calibration model.',
'limitations':'This has more constitutive flexibility than the other candidates and should be regarded as a calibrated process law, not geometry identification. Knot spacing is a design choice; slopes near the extremes are weakly determined, particularly above the largest measured closure. `patm = '+format(t[2],'.9g')+'` bar reaches its lower fitting bound. Pressure and valve effects can trade off, so `n`, `delta` and individual slopes are not uniquely identified physical mechanisms. With the fitted coefficients the fully-open atmospheric relaxation rate is approximately `0.360422` 1/s, safely inside the classical RK4 rate range at `5` s. The calibration is extended as constant fully-open conductance below the first knot and zero conductance beyond full closure, solely for numerical robustness.'+physical()}}
json.dump(model,open(OUT/(label+'.json'),'w'),indent=2)

# subcritical and choked compressible orifice with regularization
label='Compressible';z=R[label];t=z['params'];p=shared(t);lp,C=logistic(t,'1/s');p+=lp
p += [row('delta',t[3],'bar','Positive near-equilibrium regularization scale `delta`, jointly estimated; replaces the singular ideal-orifice atmospheric slope by a finite calibrated viscous-like slope.'),row('gamma',1.4,'-','Fixed calorically perfect dry-air specific-heat ratio approximation `gamma = 1.4`; no gas temperature or composition measurements are available to identify it. The perfect-gas/nozzle framework is documented in the NASA source cited in the discussion.','fixed'),row('rcrit',(2/2.4)**3.5,'-','Critical downstream/upstream pressure ratio `rcrit`, tied to `gamma` using the ideal isentropic choking condition.','tied','(2/(gamma+1))**(gamma/(gamma-1))'),row('pfloor',.01,'bar','Fixed downstream pressure floor `pfloor = 0.01` bar prevents undefined fractional powers for a numerically visited nonphysical negative absolute pressure; it is far below every supplied pressure sample and is not a valid vacuum model.','fixed')]
ratio='Max(Max(Min(p,patm),pfloor)/Max(p,patm),rcrit)'
B='(gamma/(gamma-1))*Max(p,patm)**2*(('+ratio+')**(2/gamma)-('+ratio+')**((gamma+1)/gamma))'
expr='a*flow - ('+C+')*sign(p-patm)*('+B+')/sqrt(('+B+')+delta*patm)'
model={'expressions':{'dp':expr},'parameters':p,'estimation':est(label,'The fitted coefficients are `a`, `c`, `patm`, `delta`, `vmid` and `vwidth`; ideal-gas `gamma` and its critical ratio are assumed, not estimated. All six fitted coefficients are estimated together in each simulation stage. No derivative prefit determines the submitted values.', ['a','c','patm','delta','vmid','vwidth'],['bar/(s*(l/min))','1/s','bar','bar','%','%'],'`0.0001 <= a <= 0.004` bar/(s*(l/min)), `0.0001 <= c <= 0.3` 1/s, `0.985 <= patm <= 1.01` bar, `0.003 <= delta <= 0.5` bar, `0 <= vmid <= 98` %, and `2 <= vwidth <= 70` %'),
'discussion':{'family':'Isothermal lumped ideal-gas storage with a regularized compressible isentropic-orifice outlet law, including sonic choking, and sigmoid valve-area calibration. The storage assumption is isothermal; the local outlet-flow approximation is isentropic. '+NASA,
'interpretation':'`a*flow` represents inlet gas accumulation. Define `up = Max(p,patm)` and `down = Max(Min(p,patm),pfloor)` in this discussion only. The effective ratio `'+ratio+'` stops decreasing once the ideal sonic critical ratio is reached. The quantity `'+B+'` is the squared ideal-orifice pressure drive, in bar squared. Without regularization its square root produces the usual upstream-pressure-scaled subcritical mass-flow law and its choked continuation. The signed regularized drive `sign(p-patm)*('+B+')/sqrt(('+B+')+delta*patm)` preserves zero atmospheric discharge and the high-drop gas-flow limit while supplying finite near-equilibrium relaxation. `c` incorporates area, discharge coefficient, temperature factors and storage conversion; it is not a separately measured geometric area. The nonnegative sigmoid calibration decreases that coefficient to zero at full closure.',
'origin':'The compressible family was proposed in the initial plan because headspace absolute pressure spans roughly atmosphere to more than twice atmosphere, where a constant-density square-root flow approximation may be inadequate. Initial pressure-squared surrogate laws did not improve validation enough; the explicit pressure-ratio/choked law was subsequently tried so compressibility has a defensible gas-flow form rather than an arbitrary extra pressure exponent. Finite atmospheric regularization is retained for the `5` s numerical step and low-drop viscous effects; its exact form is a modelling choice, not derived from ideal nozzle theory. The same monotone sigmoid endpoint calibration was selected based on its performance in the lower-dimensional outlet screen.',
'limitations':'Temperature is unmeasured, water-vapor content is unknown and the actual outlet is a valve with piping, not necessarily an ideal nozzle. `gamma` is assumed; `c` and `delta` can absorb departure from ideal isentropic flow. `patm = '+format(t[2],'.9g')+'` bar is at the lower fitting bound, so it should not be read as a precise atmospheric measurement. A substantial regularization scale means this is not a claim of exact ideal-orifice flow close to equilibrium. The fitted fully-open near-atmospheric relaxation rate is approximately `0.412` 1/s on the supplied fitted coefficients, consistent with the `5` s RK4 stability requirement. The negative-pressure floor is a numerical guard; the model is not calibrated for vacuum, supersonic transients, large temperatures or pressures well beyond the supplied range.'+physical()}}
json.dump(model,open(OUT/(label+'.json'),'w'),indent=2)

pool={'order':['SeriesPipe','Compressible','MixedOutlet','ValvePower'],'recommended':'SeriesPipe','reason':'The five-coefficient series viscous/inertial resistance balance is the most parsimonious physically explicit candidate, with exact sealed-valve behavior and a bounded small-drop relaxation rate that is safe for the required 5 s RK4 integration. Its training-only validation RMSE was 0.0387076 bar and its joint-fit supplied-data RMSE is approximately 0.032312 bar. The slightly more flexible alternatives improve supplied-data RMSE only modestly; all retain substantial correlated residuals and no independent validation remains after the final refit. This recommendation weights interpretability, numerical relaxation stability and restrained extrapolation over a small in-sample fit advantage.'}
json.dump(pool,open(OUT/'pool.json','w'),indent=2)
print('Created',pool['order'])
